type RenameResponse = {
	readonly type: 'rename';
	readonly body: Proto.RenameResponseBody;
} | {
	readonly type: 'jsxLinkedEditing';
	readonly spans: readonly Proto.TextSpan[];
};

class TypeScriptRenameProvider implements vscode.RenameProvider {

	public constructor(
		private readonly language: LanguageDescription,
		private readonly client: ITypeScriptServiceClient,
		private readonly fileConfigurationManager: FileConfigurationManager
	) { }

	public async prepareRename(
		document: vscode.TextDocument,
		position: vscode.Position,
		token: vscode.CancellationToken
	): Promise<vscode.Range | undefined> {
		const response = await this.execRename(document, position, token);
		if (!response) {
			return undefined;
		}

		switch (response.type) {
			case 'rename': {
				const renameInfo = response.body.info;
				if (!renameInfo.canRename) {
					return Promise.reject<vscode.Range>(renameInfo.localizedErrorMessage);
				}
				return typeConverters.Range.fromTextSpan(renameInfo.triggerSpan);
			}
			case 'jsxLinkedEditing': {
				return response.spans
					.map(typeConverters.Range.fromTextSpan)
					.find(range => range.contains(position));
			}
		}
	}

	public async provideRenameEdits(
		document: vscode.TextDocument,
		position: vscode.Position,
		newName: string,
		token: vscode.CancellationToken
	): Promise<vscode.WorkspaceEdit | undefined> {
		const file = this.client.toOpenTsFilePath(document);
		if (!file) {
			return undefined;
		}

		const response = await this.execRename(document, position, token);
		if (!response || token.isCancellationRequested) {
			return undefined;
		}

		switch (response.type) {
			case 'rename': {
				const renameInfo = response.body.info;
				if (!renameInfo.canRename) {
					return Promise.reject<vscode.WorkspaceEdit>(renameInfo.localizedErrorMessage);
				}

				if (renameInfo.fileToRename) {
					const edits = await this.renameFile(renameInfo.fileToRename, renameInfo.fullDisplayName, newName, token);
					if (edits) {
						return edits;
					} else {
						return Promise.reject<vscode.WorkspaceEdit>(vscode.l10n.t("An error occurred while renaming file"));
					}
				}

				return this.updateLocs(response.body.locs, newName);
			}
			case 'jsxLinkedEditing': {
				return this.updateLocs([{
					file,
					locs: response.spans.map((span): Proto.RenameTextSpan => ({ ...span })),
				}], newName);
			}
		}
	}

	public async execRename(
		document: vscode.TextDocument,
		position: vscode.Position,
		token: vscode.CancellationToken
	): Promise<RenameResponse | undefined> {
		const file = this.client.toOpenTsFilePath(document);
		if (!file) {
			return undefined;
		}

		// Prefer renaming matching jsx tag when available
		if (this.client.apiVersion.gte(API.v510) &&
			readUnifiedConfig<boolean>('preferences.renameMatchingJsxTags', true, { scope: document, fallbackSection: this.language.id }) &&
			this.looksLikePotentialJsxTagContext(document, position)
		) {
			const args = typeConverters.Position.toFileLocationRequestArgs(file, position);
			const response = await this.client.execute('linkedEditingRange', args, token);
			if (response.type !== 'response' || !response.body) {
				return undefined;
			}

			return { type: 'jsxLinkedEditing', spans: response.body.ranges };
		}

		const args: Proto.RenameRequestArgs = {
			...typeConverters.Position.toFileLocationRequestArgs(file, position),
			findInStrings: false,
			findInComments: false
		};

		return this.client.interruptGetErr(async () => {
			this.fileConfigurationManager.ensureConfigurationForDocument(document, token);
			const response = await this.client.execute('rename', args, token);
			if (response.type !== 'response' || !response.body) {
				return undefined;
			}
			return { type: 'rename', body: response.body };

		});
	}

	private looksLikePotentialJsxTagContext(document: vscode.TextDocument, position: vscode.Position): boolean {
		if (![languageIds.typescriptreact, languageIds.javascript, languageIds.javascriptreact].includes(document.languageId)) {
			return false;
		}

		const prefix = document.getText(new vscode.Range(position.line, 0, position.line, position.character));
		return /\<\/?\s*[\w\d_$.]*$/.test(prefix);
	}

	private updateLocs(
		locations: ReadonlyArray<Proto.SpanGroup>,
		newName: string
	) {
		const edit = new vscode.WorkspaceEdit();
		for (const spanGroup of locations) {
			const resource = this.client.toResource(spanGroup.file);
			for (const textSpan of spanGroup.locs) {
				edit.replace(resource, typeConverters.Range.fromTextSpan(textSpan),
					(textSpan.prefixText || '') + newName + (textSpan.suffixText || ''));
			}
		}
		return edit;
	}

	private async renameFile(
		fileToRename: string,
		fullDisplayName: string,
		newName: string,
		token: vscode.CancellationToken,
	): Promise<vscode.WorkspaceEdit | undefined> {
		// Make sure we preserve file extension if extension is unchanged or none provided
		if (!path.extname(newName)) {
			newName += path.extname(fileToRename);
		}
		else if (path.extname(newName) === path.extname(fullDisplayName)) {
			newName = newName.slice(0, newName.length - path.extname(newName).length) + path.extname(fileToRename);
		}

		const dirname = path.dirname(fileToRename);
		const newFilePath = path.join(dirname, newName);

		const args: Proto.GetEditsForFileRenameRequestArgs & { file: string } = {
			file: fileToRename,
			oldFilePath: fileToRename,
			newFilePath: newFilePath,
		};
		const response = await this.client.execute('getEditsForFileRename', args, token);
		if (response.type !== 'response' || !response.body) {
			return undefined;
		}

		const edits = typeConverters.WorkspaceEdit.fromFileCodeEdits(this.client, response.body);
		edits.renameFile(vscode.Uri.file(fileToRename), vscode.Uri.file(newFilePath));
		return edits;
	}
}

export function register(
	selector: DocumentSelector,
	language: LanguageDescription,
	client: ITypeScriptServiceClient,
	fileConfigurationManager: FileConfigurationManager,
) {
	return conditionalRegistration([
		requireSomeCapability(client, ClientCapability.Semantic),
	], () => {
		return vscode.languages.registerRenameProvider(selector.semantic,
			new TypeScriptRenameProvider(language, client, fileConfigurationManager));
	});
}

private async commitOperationCleanup(message: string | undefined, indexResources: string[], workingGroupResources: string[]) {
	if (message) {
		this.inputBox.value = await this.getInputTemplate();
	}
	this.closeDiffEditors(indexResources, workingGroupResources);

	// Accept working set changes across all chat sessions
	const resources = indexResources.length !== 0
		? indexResources.map(r => Uri.file(r))
		: workingGroupResources.map(r => Uri.file(r));
	commands.executeCommand('_chat.editSessions.accept', resources);

	// Clear AI contribution tracking for committed resources
	commands.executeCommand('_aiEdits.clearAiContributions', resources);
}

private static readonly AI_CO_AUTHOR_TRAILER = 'Co-authored-by: Copilot <copilot@github.com>';

private async appendAICoAuthorTrailer(
	message: string | undefined,
	indexResources: string[],
	workingGroupResources: string[]
): Promise<string | undefined> {
	if (!message) {
		return message;
	}

	const chatConfig = workspace.getConfiguration('chat');
	if (chatConfig.get<boolean>('disableAIFeatures', false)) {
		return message;
	}

	const config = workspace.getConfiguration('git', Uri.file(this.root));
	const addAICoAuthor = config.get<'off' | 'chatAndAgent' | 'all'>('addAICoAuthor', 'off');

	if (addAICoAuthor === 'off') {
		return message;
	}

	// Don't add if trailer is already present
	if (message.includes(Repository.AI_CO_AUTHOR_TRAILER)) {
		return message;
	}

	const resources = indexResources.length !== 0
		? indexResources.map(r => Uri.file(r))
		: workingGroupResources.map(r => Uri.file(r));

	if (resources.length === 0) {
		return message;
	}

	try {
		const level = addAICoAuthor === 'all' ? 'all' : 'chatAndAgent';
		const hasAiContributions = await commands.executeCommand<boolean>('_aiEdits.hasAiContributions', resources, level);
		if (hasAiContributions) {
			// Ensure proper trailer formatting: blank line before trailers
			const trimmed = message.trimEnd();
			return `${trimmed}\n\n${Repository.AI_CO_AUTHOR_TRAILER}`;
		}
	} catch {
		// Command may not be available (e.g., in web environment)
	}

	return message;
}

private commitOperationGetOptimisticResourceGroups(opts: CommitOptions): GitResourceGroups {
	let untrackedGroup: Resource[] | undefined = undefined,
		workingTreeGroup: Resource[] | undefined = undefined;

	if (opts.all === 'tracked') {
		workingTreeGroup = this.workingTreeGroup.resourceStates
			.filter(r => r.type === Status.UNTRACKED);
	} else if (opts.all) {
		untrackedGroup = workingTreeGroup = [];
	}

	return { indexGroup: [], mergeGroup: [], untrackedGroup, workingTreeGroup };
}

async clean(resources: Uri[]): Promise<void> {
	await this.run(
		Operation.Clean(!this.optimisticUpdateEnabled()),
		async () => {
			const toClean: string[] = [];
			const toCheckout: string[] = [];
			const submodulesToUpdate: string[] = [];
			const resourceStates = [...this.workingTreeGroup.resourceStates, ...this.untrackedGroup.resourceStates];

			resources.forEach(r => {
				const fsPath = r.fsPath;

				for (const submodule of this.submodules) {
					if (path.join(this.root, submodule.path) === fsPath) {
						submodulesToUpdate.push(fsPath);
						return;
					}
				}

				const raw = r.toString();
				const scmResource = find(resourceStates, sr => sr.resourceUri.toString() === raw);

				if (!scmResource) {
					return;
				}

				switch (scmResource.type) {
					case Status.UNTRACKED:
					case Status.IGNORED:
						toClean.push(fsPath);
						break;

					default:
						toCheckout.push(fsPath);
						break;
				}
			});

			if (toClean.length > 0) {
				await this._clean(toClean);
			}

			if (toCheckout.length > 0) {
				try {
					await this.repository.checkout('', toCheckout);
				} catch (err) {
					if (err.gitErrorCode !== GitErrorCodes.BranchNotYetBorn) {
						throw err;
					}
				}
			}

			if (submodulesToUpdate.length > 0) {
				await this.repository.updateSubmodules(submodulesToUpdate);

async commit(message: string | undefined, opts: CommitOptions = Object.create(null)): Promise<void> {
	const indexResources = [...this.indexGroup.resourceStates.map(r => r.resourceUri.fsPath)];
	const workingGroupResources = opts.all && opts.all !== 'tracked' ?
		[...this.workingTreeGroup.resourceStates.map(r => r.resourceUri.fsPath)] : [];

	if (this.rebaseCommit) {
		await this.run(
			Operation.RebaseContinue,
			async () => {
				if (opts.all) {
					const addOpts = opts.all === 'tracked' ? { update: true } : {};
					await this.repository.add([], addOpts);
				}

				await this.repository.rebaseContinue();
				await this.commitOperationCleanup(message, indexResources, workingGroupResources);
			},
			() => this.commitOperationGetOptimisticResourceGroups(opts));
	} else {
		// Set post-commit command to render the correct action button
		this.commitCommandCenter.postCommitCommand = opts.postCommitCommand;

		await this.run(
			Operation.Commit,
			async () => {
				if (opts.all) {
					const addOpts = opts.all === 'tracked' ? { update: true } : {};
					await this.repository.add([], addOpts);
				}

				delete opts.all;

				if (opts.requireUserConfig === undefined || opts.requireUserConfig === null) {
					const config = workspace.getConfiguration('git', Uri.file(this.root));
					opts.requireUserConfig = config.get<boolean>('requireGitUserConfig');
				}

				// Add AI co-author trailer if applicable
				message = await this.appendAICoAuthorTrailer(message, indexResources, workingGroupResources);

				await this.repository.commit(message, opts);
				await this.commitOperationCleanup(message, indexResources, workingGroupResources);
			},
			() => this.commitOperationGetOptimisticResourceGroups(opts));

		// Execute post-commit command
		await this.run(Operation.PostCommitCommand, async () => {
			await this.commitCommandCenter.executePostCommitCommand(opts.postCommitCommand);
		});
	}
}

