	if (triggerKind === NewSymbolNameTriggerKind.Invoke) {
		return true;
	} else if (this._authService.copilotToken?.isFreeUser || this._authService.copilotToken?.isNoAuthUser) {
		return false;
	} else {
		return this._configurationService.getConfig(ConfigKey.AutomaticRenameSuggestions);
	}
}

/**
 * @throws {Error} with `message = 'CopilotFeatureUnavailableOrDisabled' if the feature is not available
 * @throws {Error} with `message = 'CopilotIgnoredDocument' if the document is Copilot-ignored
 */
async provideNewSymbolNames(_document: vscode.TextDocument, range: vscode.Range, triggerKind: NewSymbolNameTriggerKind, token: vscode.CancellationToken): Promise<NewSymbolName[] | null> {
	const document = TextDocumentSnapshot.create(_document);

	let cancellationReason: ProvideCallCancellationReason = ProvideCallCancellationReason.None;

	const beforeDelaySW = new StopWatch();

	// @ulugbekna: capture the symbol name that is being renamed before an await to avoid document being changed under us
	const currentSymbolName = document.getText(range);

	if (!this.isEnabled(triggerKind)) {
		throw new Error('CopilotFeatureUnavailableOrDisabled');
	}

	if (await this._ignoreService.isCopilotIgnored(document.uri)) {
		throw new Error('CopilotIgnoredDocument');
	}

	const languageId = document.languageId;

	let expectedDelayBeforeFetch: number | undefined;
	let timeElapsedBeforeDelay: number | undefined;

	if (token.isCancellationRequested) {
		cancellationReason = ProvideCallCancellationReason.AfterEnablementCheck;
	} else {
		const endpoint = await this._endpointProvider.getChatEndpoint('copilot-utility-small');
		expectedDelayBeforeFetch = this.delayBeforeFetchMs;

		if (token.isCancellationRequested) {
			cancellationReason = ProvideCallCancellationReason.AfterRunParametersFetch;
		} else {

			const sw = new StopWatch(false);

			sw.reset();
			const promptRenderResult = await this._computePrompt(document, range, endpoint, token);
			const promptConstructionTime = sw.elapsed();

			if (token.isCancellationRequested) {
				cancellationReason = ProvideCallCancellationReason.AfterPromptCompute;
			} else {

				timeElapsedBeforeDelay = beforeDelaySW.elapsed();

				let actualDelayBeforeFetch: number | undefined;
				if (triggerKind === NewSymbolNameTriggerKind.Automatic) {
					actualDelayBeforeFetch = expectedDelayBeforeFetch ? Math.max(0, expectedDelayBeforeFetch - timeElapsedBeforeDelay) : undefined;
					if (actualDelayBeforeFetch !== undefined && actualDelayBeforeFetch > 0) {
						await new Promise(resolve => setTimeout(resolve, actualDelayBeforeFetch));
					}
				}

				if (token.isCancellationRequested) {
					cancellationReason = ProvideCallCancellationReason.AfterDelay;
				} else {

					sw.reset();
					this._interactionService.startInteraction();
					const fetchResult = await endpoint.makeChatRequest(
						'renameSuggestionsProvider',
						promptRenderResult.messages,
						undefined, // TODO@ulugbekna: should we terminate on `]` (closing for JSON array that we expect to receive from the model)
						token,
						ChatLocation.Other,
						undefined,
						{
							top_p: undefined,
							temperature: undefined
						},
						true
					);
					const fetchTime = sw.elapsed();

					// @ulugbekna: only show the quota exceeded dialog when the user manually invoked rename suggestions.
					// For automatic triggers (e.g., when pressing F2), showing a modal dialog steals focus from the
					// rename widget and cancels the user's rename action - see https://github.com/microsoft/vscode/issues/319414
					if (RenameSuggestionsProvider.shouldShowQuotaExceededDialog(triggerKind, fetchResult.type, this._authService.copilotToken?.isNoAuthUser ?? false)) {
						await this._notificationService.showQuotaExceededDialog({ isNoAuthUser: this._authService.copilotToken?.isNoAuthUser ?? false });
					}

					if (token.isCancellationRequested) {
						cancellationReason = ProvideCallCancellationReason.AfterFetchStarted;
					}

					switch (fetchResult.type) {
						case ChatFetchResponseType.Success: {
							const reply = fetchResult.value;
							const { replyFormat, symbolNames, redundantCharCount: responseUnusedCharCount } = RenameSuggestionsProvider.parseResponse(reply);
							if (replyFormat === 'unknown') {
								this._sendInternalTelemetry({ languageId, reply });
							}
							this._sendPublicTelemetry({
								triggerKind,
								languageId,
								cancellationReason,
								fetchResultType: fetchResult.type,
								promptConstructionTime,
								promptTokenCount: promptRenderResult.tokenCount,
								expectedDelayBeforeFetch,
								actualDelayBeforeFetch,
								timeElapsedBeforeDelay,
								successResponseCharCount: reply.length,
								responseUnusedCharCount,
								fetchTime,
								replyFormat,
								symbolNamesCount: symbolNames.length,
							});

							const processedSymbolNames = RenameSuggestionsProvider.preprocessSymbolNames({ currentSymbolName, newSymbolNames: symbolNames, languageId });
							return processedSymbolNames.map(symbolName => new NewSymbolName(symbolName, [NewSymbolNameTag.AIGenerated]));
						}
						default: {
							this._sendPublicTelemetry({
								triggerKind,
								languageId,
								cancellationReason,
								fetchResultType: fetchResult.type,
								promptConstructionTime,
								promptTokenCount: promptRenderResult.tokenCount,
								expectedDelayBeforeFetch,
								actualDelayBeforeFetch,
								timeElapsedBeforeDelay,
								fetchTime,
							});
							return null;
						}
					}
				}
			}
		}

// - FIXME: currently, we fail with very large definitions such as big classes or functions -- we need summarization by category, e.g., remove method implementations if we're renaming a class
// - idea: include hover info (i.e., usually type info & corresponding document) of the symbol being renamed in the prompt
// - idea: include usages of the symbol being renamed in the prompt
// - idea: include peer symbols (e.g., other methods in the same class) in the prompt for copilot to see conventions in the code
private _computePrompt(document: TextDocumentSnapshot, range: vscode.Range, chatEndpoint: IChatEndpoint, token: vscode.CancellationToken) {
	const promptRenderer = PromptRenderer.create(
		this._instaService,
		chatEndpoint,
		RenameSuggestionsPrompt,
		{
			document,
			range
		}
	);
	return promptRenderer.render(undefined, token);
}

public static preprocessSymbolNames({ currentSymbolName, newSymbolNames, languageId }: { currentSymbolName: string; newSymbolNames: string[]; languageId: string }): string[] {

	const currentNameConvention = guessNamingConvention(currentSymbolName);

	let targetNamingConvention: NamingConvention;
	switch (currentNameConvention) {
		case NamingConvention.LowerCase:
			if (languageId === 'python') {
				targetNamingConvention = NamingConvention.SnakeCase;
			} else {
				targetNamingConvention = NamingConvention.CamelCase;
			}
			break;
		case NamingConvention.Uppercase:
		case NamingConvention.CamelCase:
		case NamingConvention.PascalCase:
		case NamingConvention.SnakeCase:
		case NamingConvention.ScreamingSnakeCase:
		case NamingConvention.CapitalSnakeCase:
		case NamingConvention.KebabCase:
		case NamingConvention.Capitalized:
		case NamingConvention.Unknown:
			targetNamingConvention = currentNameConvention;
			break;
		default: {
			const _exhaustiveCheck: never = currentNameConvention;
			return _exhaustiveCheck;
		}
	}

	if (targetNamingConvention === NamingConvention.Unknown) {
		return newSymbolNames;
	}

	return newSymbolNames.map(newSymbolName => enforceNamingConvention(newSymbolName, targetNamingConvention));
}

/**
 * Determines whether to show the quota exceeded dialog for a rename suggestions fetch result.
 *
 * The dialog is only shown for manually-invoked rename suggestions ({@link NewSymbolNameTriggerKind.Invoke}).
 * For automatic triggers (e.g., when pressing F2), showing a modal dialog steals focus from the rename
 * widget and cancels the user's rename action - see https://github.com/microsoft/vscode/issues/319414
 */
public static shouldShowQuotaExceededDialog(triggerKind: NewSymbolNameTriggerKind, fetchResultType: ChatFetchResponseType, isNoAuthUser: boolean): boolean {
	if (triggerKind !== NewSymbolNameTriggerKind.Invoke) {
		return false;
	}
	return fetchResultType === ChatFetchResponseType.QuotaExceeded
		|| (fetchResultType === ChatFetchResponseType.RateLimited && isNoAuthUser);
}

public static parseResponse(reply: string): { replyFormat: ReplyFormat; redundantCharCount: number; symbolNames: string[] } {
	const parsedAsJSONStringArray = RenameSuggestionsProvider._parseReplyAsJSONStringArray(reply);
	if (parsedAsJSONStringArray !== undefined) {
		return parsedAsJSONStringArray;
	}

	const parsedAsList = RenameSuggestionsProvider._parseReplyAsList(reply);
	if (parsedAsList !== undefined) {
		return parsedAsList;
	}

	return { replyFormat: 'unknown', symbolNames: [], redundantCharCount: reply.length };
}

/** try extracting from JSON string array */
private static _parseReplyAsJSONStringArray(reply: string) {

	const jsonArrayRe = /\[.*?\]/gs; // `s` regex flag allows matching newlines using `.`

	const matches = [...reply.matchAll(jsonArrayRe)];

	for (let i = 0; i < matches.length; i++) {
		const match = matches[i];
		try {
			const parsedJSONArray: unknown = JSON.parse(match[0]);

			if (Array.isArray(parsedJSONArray)) {

				const symbolNames = parsedJSONArray.filter(v => typeof v === 'string');

				if (symbolNames.length > 0) {
					const replyFormat: ReplyFormat = i === 0 ? 'jsonStringArray' : 'multiJsonStringArray';
					const redundantCharCount = reply.length - match[0].length;
					return { replyFormat, redundantCharCount, symbolNames: symbolNames.map(s => s.trim()) } as const;
				}
			}
		} catch (error) {
		}
	}
}

private static _parseReplyAsList(reply: string) {
	// try extracting from an ordered or unordered list
	const listLineRe = /(?:\d+[\.|\)]|[\*\-])\s*(.*)/g;
	const matches = reply.matchAll(listLineRe);

	const symbolNames: string[] = [];
	for (const match of matches) {
		let symbolName = match[1].trim();
		const punctuation = ['\'', '"', '`'];
		if (punctuation.includes(symbolName[0])) {

async executeHook(hookType: vscode.ChatHookType, hooks: vscode.ChatRequestHooks | undefined, input: unknown, sessionId?: string, token?: vscode.CancellationToken): Promise<vscode.ChatHookResult[]> {
	if (!hooks) {
		return [];
	}

	const hookCommands = hooks[hookType];
	if (!hookCommands || hookCommands.length === 0) {
		return [];
	}

	const hookCount = hookCommands.length;
	const overallStopWatch = StopWatch.create();
	let hasError = false;
	let hasCaughtException = false;

	try {
		// Flush transcript before running hooks so scripts see up-to-date content
		let transcriptPath: vscode.Uri | undefined;
		if (sessionId) {
			await raceTimeout(this._sessionTranscriptService.flush(sessionId), 500);
			transcriptPath = this._sessionTranscriptService.getTranscriptPath(sessionId);
		}

		// Build common input properties merged with caller-specific input
		const commonInput = {
			timestamp: new Date().toISOString(),
			hook_event_name: hookType,
			...(sessionId ? { session_id: sessionId } : undefined),
			...(transcriptPath ? { transcript_path: transcriptPath.fsPath } : undefined),
		};
		const fullInput = (typeof input === 'object' && input !== null)
			? { ...commonInput, ...input }
			: commonInput;

		const results: vscode.ChatHookResult[] = [];
		const effectiveToken = token ?? CancellationToken.None;
		const requestId = this._requestCounter++;

		this._logService.debug(`[ChatHookService] Executing ${hookCommands.length} hook(s) for type '${hookType}'`);
		this._log(requestId, hookType, `Executing ${hookCommands.length} hook(s)`);

		const chatSessionId = sessionId;

		for (const hookCommand of hookCommands) {
			try {
				// Include per-command cwd in the input
				const commandInput = hookCommand.cwd
					? { ...fullInput, cwd: hookCommand.cwd.fsPath }
					: fullInput;

				this._log(requestId, hookType, `Running: ${JSON.stringify(hookCommand)}`);
				const inputForLog = this._redactForLogging(commandInput as Record<string, unknown>);
				this._log(requestId, hookType, `Input: ${JSON.stringify(inputForLog)}`);

				const hookToolName = (commandInput as { tool_name?: unknown }).tool_name;
				const hookToolNamesJson = typeof hookToolName === 'string' ? JSON.stringify([hookToolName]) : undefined;

				const span = this._otelService.startSpan(`execute_hook ${hookType}`, {
					kind: SpanKind.INTERNAL,
					attributes: {
						[GenAiAttr.OPERATION_NAME]: GenAiOperationName.EXECUTE_HOOK,
						[CopilotChatAttr.HOOK_TYPE]: hookType,
						'copilot_chat.hook_command': hookCommand.command,
						...(chatSessionId ? { [GenAiAttr.CONVERSATION_ID]: chatSessionId } : {}),
						...(chatSessionId ? { [CopilotChatAttr.SESSION_ID]: chatSessionId } : {}),
						...(chatSessionId ? { [CopilotChatAttr.CHAT_SESSION_ID]: chatSessionId } : {}),
						...(hookToolNamesJson ? { [GitHubCopilotAttr.HOOK_TOOL_NAMES]: hookToolNamesJson } : {}),
					},
				});

				try {
					// Capture hook input for debug panel resolve
					try {
						span.setAttribute(CopilotChatAttr.HOOK_INPUT, truncateForOTel(JSON.stringify(commandInput), this._otelService.config.maxAttributeSizeChars));
					} catch { /* swallow serialization errors */ }

					const sw = StopWatch.create();
					const commandResult = await this._hookExecutor.executeCommand(hookCommand, commandInput, effectiveToken);
					const elapsed = sw.elapsed();
					span.setAttribute(GitHubCopilotAttr.HOOK_DURATION_SECONDS, elapsed / 1000);

					this._logCommandResult(requestId, hookType, commandResult, elapsed);

					// Record result on OTel span
					const resultKind = commandResult.kind === HookCommandResultKind.Success ? 'success'
						: commandResult.kind === HookCommandResultKind.NonBlockingError ? 'non_blocking_error'
							: 'error';
					span.setAttribute(CopilotChatAttr.HOOK_RESULT_KIND, resultKind);

					const hookDecision = commandResult.kind === HookCommandResultKind.Error
						? 'block'
						: commandResult.kind === HookCommandResultKind.NonBlockingError
							? 'non_blocking_error'
							: 'pass';
					span.setAttribute(GitHubCopilotAttr.HOOK_DECISION, hookDecision);

					if (commandResult.kind === HookCommandResultKind.Error || commandResult.kind === HookCommandResultKind.NonBlockingError) {
						hasError = true;
						// Record exit code on error
						if (commandResult.exitCode !== undefined) {
							span.setAttribute('copilot_chat.hook_exit_code', commandResult.exitCode);
						}
						// Error output goes to span status message (displayed as errorMessage in resolve)
						span.setStatus(SpanStatusCode.ERROR, typeof commandResult.result === 'string' ? commandResult.result : undefined);
					} else {
						span.setStatus(SpanStatusCode.OK);
						// Capture hook output for debug panel resolve (success only — errors go to errorMessage)
						try {
							const output = typeof commandResult.result === 'string' ? commandResult.result : JSON.stringify(commandResult.result);
							if (output) {
								span.setAttribute(CopilotChatAttr.HOOK_OUTPUT, truncateForOTel(output, this._otelService.config.maxAttributeSizeChars));
							}
						} catch { /* swallow serialization errors */ }
					}

					const result = this._toHookResult(hookType, commandResult);
					results.push(result);

					// If stopReason is set (including empty string for "stop without message"), stop processing remaining hooks
					if (result.stopReason !== undefined) {
						// A stop signal from a successful hook still counts as a block.
						if (hookDecision === 'pass') {
							span.setAttribute(GitHubCopilotAttr.HOOK_DECISION, 'block');
						}
						this._log(requestId, hookType, `Stopping: ${result.stopReason}`);

			return {
				resultKind: 'warning',
				output: undefined,
				warningMessage: errorMessage,
			};
		}
		case HookCommandResultKind.Success: {
			if (typeof commandResult.result !== 'object') {
				return {
					resultKind: 'success',
					output: commandResult.result,
				};
			}

			// Extract common fields (continue, stopReason, systemMessage)
			const resultObj = commandResult.result as Record<string, unknown>;
			const stopReason = typeof resultObj['stopReason'] === 'string' ? resultObj['stopReason'] : undefined;
			const continueFlag = resultObj['continue'];
			const systemMessage = typeof resultObj['systemMessage'] === 'string' ? resultObj['systemMessage'] : undefined;

			// Handle continue field: when false, stopReason is effective
			let effectiveStopReason = stopReason;
			if (continueFlag === false && !effectiveStopReason) {
				effectiveStopReason = '';
			}

			// Check hookEventName at top level — if present and mismatched, skip this result
			const topLevelHookEventName = resultObj['hookEventName'];
			if (typeof topLevelHookEventName === 'string' && !isCompatibleHookEventName(topLevelHookEventName, hookType)) {
				this._logService.trace(`[ChatHookService] Ignoring result with mismatched hookEventName '${topLevelHookEventName}' (expected '${hookType}')`);
				return {
					resultKind: 'success',
					output: undefined,
				};
			}

			// Check hookEventName inside hookSpecificOutput — if mismatched, strip hookSpecificOutput but keep the rest
			let stripHookSpecificOutput = false;
			const hookSpecificOutput = resultObj['hookSpecificOutput'];
			if (typeof hookSpecificOutput === 'object' && hookSpecificOutput !== null) {
				const nestedHookEventName = (hookSpecificOutput as Record<string, unknown>)['hookEventName'];
				if (typeof nestedHookEventName === 'string' && !isCompatibleHookEventName(nestedHookEventName, hookType)) {
					this._logService.trace(`[ChatHookService] Stripping hookSpecificOutput with mismatched hookEventName '${nestedHookEventName}' (expected '${hookType}')`);
					stripHookSpecificOutput = true;
				}
			}

			// Extract hook-specific output (everything except common fields)
			const commonFields = new Set(['continue', 'stopReason', 'systemMessage']);
			if (stripHookSpecificOutput) {
				commonFields.add('hookSpecificOutput');
			}
			const hookOutput: Record<string, unknown> = {};
			for (const [key, value] of Object.entries(resultObj)) {
				if (value !== undefined && !commonFields.has(key)) {
					hookOutput[key] = value;
				}
			}

			return {
				resultKind: 'success',
				stopReason: effectiveStopReason,
				warningMessage: systemMessage,
				output: Object.keys(hookOutput).length > 0 ? hookOutput : undefined,
			};
		}
		default:
			return {
				resultKind: 'warning',
				warningMessage: `Unexpected hook command result kind: ${(commandResult as IHookCommandResult).kind}`,
				output: undefined,
			};
	}
}

